  async function run(cs,scenes){const results=[],records=[];for(const c of cs){const trials=[];for(const s of scenes){const face=R.render(c,s);bed.replaceChildren(face);const observation=R.measure(face,c,s),result=Q.evaluate(observation,s);trials.push(result);records.push({candidate:c.id,...result,observation});}results.push(Q.summarize(c.id,trials));$('#status').textContent=`Измерено ${results.length}/${cs.length} · ${scenes.length} сцен на вариант`;await new Promise(resolve=>setTimeout(resolve,0));}bed.replaceChildren();return {results,records};}
  async function generation(){const n=campaign.generations.length+1;if(n>3)return;$('#start').disabled=$('#next').disabled=true;const prev=campaign.generations.at(-1),cs=n===1?Q.initial():Q.evolve(prev.candidates,prev.results,n);Q.validateCatalog(cs,campaign.generations.flatMap(g=>g.candidates));const measured=await run(cs,training);campaign.generations.push({generation:n,candidates:cs,...measured});output();paint(cs);$('#status').textContent=`Поколение ${n}: ${cs.length} вариантов, ${measured.results.filter(r=>r.failures===0).length} прошли все авторские сцены.`;$('#next').disabled=n===3;$('#final').disabled=n!==3;}
