  $('#holdout').onclick=async()=>{try{const payload=JSON.parse($('#inputs').value);if(!Array.isArray(payload.scenes)||!payload.scenes.length||!campaign.finalIds.length)throw Error('Нужны сцены и замороженные финалисты');const all=campaign.generations.flatMap(g=>g.candidates),cs=campaign.finalIds.map(id=>all.find(c=>c.id===id)),measured=await run(cs,payload.scenes);campaign.holdouts.push({attempt:campaign.holdouts.length+1,scenes:payload.scenes,...measured,qualification:cs.map(c=>({id:c.id,...Q.qualifyTrials(c.id,payload.scenes,measured.records.filter(r=>r.candidate===c.id))}))});campaign.reviewScenes=payload.scenes;setScenes(payload.scenes);output();paint(cs);$('#status').textContent=`Контроль: ${measured.results.map(r=>r.id+' '+r.failedScenes+'/'+r.trials).join(' · ')}`;}catch(e){$('#status').textContent=e.message;}};
  const prepareFirstRepair=$('#repair').onclick,measureFirstRepair=$('#repairRun').onclick;
  $('#repair').onclick=()=>{if(campaign.generations.length!==4)return prepareFirstRepair();try{campaign.pendingLimb=Q.limbRepair(campaign.generations);output();paint(campaign.pendingLimb);$('#status').textContent='Последние два места ремонтного поколения: дуга Земли и две пары полей. Зафиксировать перед замером.';}catch(e){$('#status').textContent=e.message;}};
